Ltac elim_div x d :=
  let q := fresh "q" in let r := fresh "rm" in
  pose proof (Z.div_mod x d ltac:(lia)); pose proof (Z.mod_pos_bound x d ltac:(lia));
  set (q := x / d) in *; set (r := x mod d) in *; clearbody q r.

